import React from "react";
import { UserProfile } from "../interfaces";
import Navigation from "../components/nav";
import { useTranslation } from "gatsby-plugin-react-i18next";
import data from "../data/data.json";
import SEO from "./seo";
import Logo from "../components/logo";
import { LayoutProps } from "../interfaces";

const userData: UserProfile = data;

const Layout: React.FC<LayoutProps> = ({
  children,
  data,
  iconAndTextColor,
  footerLogoFill,
  footerColorText = "text-Tofu",
  bgColorPage,
  bgImage,
  bgPosition = "top center",
  footerBackground,
  paddingBottomClassBackground = "pb-[100%]",
  overlayGradient = true,
}) => {
  const { t } = useTranslation();
  const currentYear = new Date().getFullYear();
  const isVideo = typeof bgImage === "string" && /\.(mp4|webm|ogg)$/i.test(bgImage);

  // Mapeo de clases Tailwind personalizadas a colores hex
  const tailwindColorMap: Record<string, string> = {
      "DeepSea": "#101919",
      "Trooper": "#687B7E",
      "Kayaking": "#007479",
      "DarkSea": "#304E53",
      "Tofu": "#EAE6DA",
      "Oatmeal": "#CCC4B4",
      "CoralRed": "#D0342C",
  };

  // Función para convertir hex a rgba
  const hexToRgba = (hex: string, alpha: number = 1): string => {
    let parsed = hex.replace("#", "");
    if (parsed.length === 3) parsed = parsed.split("").map(c => c + c).join("");
    const r = parseInt(parsed.substring(0, 2), 16);
    const g = parseInt(parsed.substring(2, 4), 16);
    const b = parseInt(parsed.substring(4, 6), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  };

  // Determinar el color base desde bgColorPage (basado en clases Tailwind)
  const tailwindClass = bgColorPage?.replace("bg-", "");
  const baseHex = tailwindClass ? tailwindColorMap[tailwindClass] : "#000000";
  const gradientBaseColor = hexToRgba(baseHex, 1);
  return (
    <div className={`relative min-h-screen flex flex-col bg-${bgColorPage} text-light overflow-hidden ${gradientBaseColor || ""}`}>
      <SEO data={data || userData} />
      {/* Background image */}
      <div className="absolute top-0 left-0 w-full">

        {isVideo ? (
          <video
            autoPlay
            loop
            muted
            playsInline
            className="w-[300%] sm:w-full max-w-[300%] sm:max-w-full h-full object-cover"
          >
            <source src={bgImage} type={`video/${bgImage.split('.').pop()}`} />
            Your browser does not support the video tag.
          </video>
        ) : (

        <div
          className={`${paddingBottomClassBackground} w-full`}
          style={{
            // paddingBottom: `${(1760 / 1920) * 100}%`, // ≈ 91.67%
            backgroundImage: `url(${bgImage})`,
            backgroundSize: "cover",
            backgroundRepeat: "no-repeat",
            backgroundPosition: bgPosition,
          }}
        ></div>
        )}
        {/* Gradient Overlay */}
          {overlayGradient && (
            <div
              className="absolute bottom-0 w-full h-48 pointer-events-none"
              style={{
                background: `linear-gradient(to top, ${gradientBaseColor}, transparent)`,
              }}
            />
          )}
      </div>

      <Navigation iconAndTextColor={iconAndTextColor} />
      <div className={styles.bodyContainer}>
        <div className="relative mt-[3.75rem]">{children}</div>
      </div>

      <footer className={styles.footerContainer}
      style={{ background: footerBackground || "transparent" }}
      >
        <div className="flex flex-col sm:flex-row min-h-24 sm:min-h-96 w-full">
          <div className="flex flex-col py-2 sm:py-8 mx-auto sm:ml-0 justify-end">
            <Logo className={`${footerLogoFill} w-[46px] h-[14px]`} />
          </div>

          <div className="flex flex-col w-full justify-end">
            <div className={`${footerColorText} justify-end p-4 text-center sm:text-end`}>
              &copy; {currentYear} {data?.name}
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default Layout;

const styles = {
  bodyContainer: "mx-auto w-full flex flex-col",
  header: "mt-6 flex flex-row justify-center items-center py-4 sm:py-0 w-full",
  footerContainer: "flex flex-col text-light w-full px-12 absolute bottom-0 ",
  logoContainer:
    "flex justify-center items-center shadow-2xl rounded-2xl relative",
  logo: "w-40 sm:w-[22rem] h-auto rounded-2xl",
};
